// Writes the ABI the front end needs as a typed `as const` module.
//
//   npx hardhat run scripts/export-abi.ts
//
// The generated file is committed, so the front end builds without the Hardhat workspace
// (for example on Vercel, where only `frontend/` is built).

import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

import { artifacts } from "hardhat";

const outDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../frontend/src/contracts");

const artifact = await artifacts.readArtifact("LinearStaking");
const source =
  "// Generated by scripts/export-abi.ts from the compiled LinearStaking contract.\n" +
  "// Do not edit by hand: run `npm run export-abi` in the repository root instead.\n\n" +
  `export const linearStakingAbi = ${JSON.stringify(artifact.abi, null, 2)} as const;\n`;

await mkdir(outDir, { recursive: true });
await writeFile(path.join(outDir, "linearStakingAbi.ts"), source);
console.log(`Wrote ${artifact.abi.length} ABI entries to frontend/src/contracts/linearStakingAbi.ts`);
